CREATE TABLE `cards` (
  `id` varchar(24) NOT NULL,
  `code` varchar(24) NOT NULL,
  `slug` varchar(200) NOT NULL,
  `title_fa` varchar(500) NOT NULL,
  `title_en` varchar(500) DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `category_id` varchar(24) NOT NULL,
  `macro_domain` varchar(120) DEFAULT NULL,
  `paradigm` varchar(80) DEFAULT NULL,
  `level` varchar(80) DEFAULT NULL,
  `card_type` varchar(80) DEFAULT NULL,
  `year` int(11) DEFAULT NULL,
  `theorists_text` text DEFAULT NULL,
  `approach` text DEFAULT NULL,
  `core_logic` mediumtext DEFAULT NULL,
  `constructs` mediumtext DEFAULT NULL,
  `example` mediumtext DEFAULT NULL,
  `critique` mediumtext DEFAULT NULL,
  `detailed_analysis` longtext DEFAULT NULL,
  `related_approaches` text DEFAULT NULL,
  `recommended_sources` text DEFAULT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),
  `views` int(11) NOT NULL DEFAULT 0,
  `comments_count` int(11) NOT NULL DEFAULT 0,
  `status` varchar(20) NOT NULL DEFAULT 'published',
  `published_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

