--
-- Table structure for table `categories`
--

CREATE TABLE `categories` (
  `id` varchar(24) NOT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(120) NOT NULL,
  `macro_domain` varchar(120) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `icon` varchar(64) DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `cards_count` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `categories`
--

INSERT INTO `categories` (`id`, `name`, `slug`, `macro_domain`, `description`, `icon`, `sort_order`, `cards_count`) VALUES
('cat-1', 'نظریه‌های اثرات رسانه و چارچوب‌بندی', 'c1', 'جامعه‌شناسی، مخاطب و تأثیر', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «جامعه‌شناسی، مخاطب و تأثیر» — تمرکز بر نحوه پردازش پیام توسط فرد، تأثیر رسانه بر افکار عمومی، تغییر نگرش و الگوهای مصرف رسانه‌ای.', '👥', 1, 0),
('cat-10', 'نظریه‌های انتقادی و فرهنگی', 'c10', 'قدرت، اقتصاد و نقد', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «قدرت، اقتصاد و نقد» — بررسی رسانه به عنوان نهاد بازتولیدکننده هژمونی، کالایی‌شدن فرهنگ و نابرابری‌های ساختاری.', '⚖️', 10, 0),
('cat-11', 'نظریه‌های روان‌شناختی و اثرات رسانه', 'c11', 'جامعه‌شناسی، مخاطب و تأثیر', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «جامعه‌شناسی، مخاطب و تأثیر» — تمرکز بر نحوه پردازش پیام توسط فرد، تأثیر رسانه بر افکار عمومی، تغییر نگرش و الگوهای مصرف رسانه‌ای.', '👥', 11, 0),
('cat-12', 'نظریه‌های رسانه دیجیتال و پلتفرم', 'c12', 'عصر شبکه‌ها و داده‌ها', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «عصر شبکه‌ها و داده‌ها» — تحلیل گذار از رسانه‌های توده‌ای به اقتصاد پلتفرمی، استخراج داده‌ها و حاکمیت الگوریتمی.', '🌐', 12, 0),
('cat-13', 'روابط عمومی و مدیریت شهرت', 'c13', 'سازمان و حرفه', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «سازمان و حرفه» — مطالعه رویه‌های نهادی، دروازه‌بانی اخبار، مدیریت بحران، حس‌سازی سازمانی و تطبیق با اختلالات دیجیتال.', '🏢', 13, 2),
('cat-14', 'ترغیب، رفتار و ارتباطات راهبردی', 'c14', 'جامعه‌شناسی، مخاطب و تأثیر', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «جامعه‌شناسی، مخاطب و تأثیر» — تمرکز بر نحوه پردازش پیام توسط فرد، تأثیر رسانه بر افکار عمومی، تغییر نگرش و الگوهای مصرف رسانه‌ای.', '👥', 14, 0),
('cat-15', 'روابط عمومی راهبردی، برند و ارتباطات یکپارچه', 'c15', 'سازمان و حرفه', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «سازمان و حرفه» — مطالعه رویه‌های نهادی، دروازه‌بانی اخبار، مدیریت بحران، حس‌سازی سازمانی و تطبیق با اختلالات دیجیتال.', '🏢', 15, 0),
('cat-16', 'اقتصاد و مدیریت رسانه', 'c16', 'بنیادها و پیام', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «بنیادها و پیام» — تمرکز بر ماهیت ارتباط، بوم‌شناسی ابزارها، و چگونگی تولید و رمزگشایی معنا در متون رسانه‌ای.', '📚', 16, 0),
('cat-17', 'مدیریت راهبردی و اقتصاد رقابت', 'c17', 'قدرت، اقتصاد و نقد', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «قدرت، اقتصاد و نقد» — بررسی رسانه به عنوان نهاد بازتولیدکننده هژمونی، کالایی‌شدن فرهنگ و نابرابری‌های ساختاری.', '⚖️', 17, 0),
('cat-18', 'اقتصاد رفتاری، سازمان و تصمیم‌گیری', 'c18', 'سازمان و حرفه', 'زیرحوزه مطالعاتی ذیل کلان‌حوزه «سازمان و حرفه» — مطالعه رویه‌های نهادی، دروازه‌بانی اخبار، مدیریت بحران، حس‌سازی سازمانی و تطبیق با اختلالات دیجیتال.', '🏢', 18, 0),
