INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-423', 'card', 'card-423', 'mc-423', 'شش درجه جدایی', 'Six Degrees of Separation', 'theory', 'یافته میلگرام (۱۹۶۷) مبنی بر میانگین حدود ۶ واسطۀ آشنایی میان دو فرد دلخواه، مدلی است که واتس و استروگاتس (۱۹۹۸) با ترکیب خوشه‌بندی محلی بالا و فاصلۀ میانگین کوتاه آن را به‌شکل شبکه‌های small-world فرموله کردند.', 'https://resaname.ir/cards/card-423', 'fa', NULL, NULL, '33dad2854a4c6da5d4fc557fe3686f987bba238b6517a37ac4dc1bc0e7f84030', '2026-10-14 01:36:07', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-423-1', 'doc-card-423', 'definition', 'تعریف', 'شبکه‌های اجتماعی و نظریه شبکه

آزمایش جهان کوچک؛ هر دو فرد دلخواه بر روی کره زمین به‌طور میانگین از طریق زنجیره‌ای از ۶ رابط بین‌فردی به یکدیگر متصل می‌شوند.', '3bf16bdfeda3eafc8e6ad06834b94794e9b3c2bc8ae204c97e6f8fb58fbe5542', 1, NOW(), NOW()),
('sec-card-423-2', 'doc-card-423', 'theoretical_framework', 'چارچوب نظری', '۱. آزمایش: میلگرام و «مسئله‌ی جهان کوچک»
استنلی میلگرام (Stanley Milgram) در سال ۱۹۶۷، در مقاله‌ی «مسئله‌ی جهان کوچک» (The Small World Problem) در American Psychologist، آزمایش مشهور خود را منتشر کرد. طرح: مشارکت‌کنندگان (اغلب ساکنان اووما، نبراسکا) نامه‌ای برای تحویل به یک فرد مقصد (اغلب یک بورس‌دار در بوستون) گرفتند، با این شرط که نامه فقط به‌صورت «شخصی» به کسی که می‌شناسند (با نام کوچک) تحویل داده شود — تماس مستقیم با مقصد ممنوع بود.

نتیجه: اکثر نامه‌ها به مقصد رسیدند و طول زنجیره‌ها در میانگین حدود «شش» واسطه بود. این یافته، همراه با ایده‌ی «شش درجه‌ی جدایی» که از سال‌های ۱۹۳۰ در دایره‌های هنری و آکادمیک (از داستان کوتاه یک نویسنده‌ی مجاری تا طرح‌های جامعه‌شناسان) می‌چرخید، به «مسئله‌ی جهان کوچک» (Small-World Problem) تبدیل شد: هر', '0eaaae46704fa442b7d3b502365e6adc7ea519434ec0c40ea95e6f0d83c635c3', 2, NOW(), NOW()),
('sec-card-423-3', 'doc-card-423', 'components', 'اجزای نظری', '• زنجیره‌ی جهان کوچک (Small-World Chain): زنجیره‌ی کوتاه از پیوندهای میان‌فردی که دو غریبه را به یکدیگر وصل می‌کند.
• میانگین طول زنجیره: حدود شش پیوند واسط در مطالعه‌ی میلگرام.
• خوشه‌بندی محلی و مسیرهای کوتاه: ساختار «جهان کوچک» (وَتس و استروگاتس، ۱۹۹۸) — هم‌زمانی تراکم محلی و میانگین کوتاه فاصله.
• همگونی در جست‌وجوی واسطه: افراد برای عبور زنجیره، واسطه‌هایی از محیط اجتماعی خودشان انتخاب می‌کنند.', 'eaa2da0f45941c774be11e5ba990354dfbc41a8e2f3242f39bdfdfc1d2b4a67d', 3, NOW(), NOW()),
('sec-card-423-4', 'doc-card-423', 'applications', 'کاربردها', 'دو فرد دلخواه روی کره زمین، از طریق زنجیره‌ای کوتاه از آشنایی به یکدیگر متصل‌اند.

۲. اهمیت نظری: از روان‌شناسی اجتماعی به علم شبکه
در دهه‌ی ۱۹۹۰، با رشد «علم شبکه»، مفهوم شش درجه توسط دنکان وتس و استیون استروگاتس (Watts & Strogatz, 1998) به‌شکل رسمی در مدل «شبکه‌های جهان کوچک» (Small-World Networks) ترسیم شد: شبکه‌ای که هم‌زمان (۱) «خوشه‌بندی محلی» بالایی دارد (دوستان ما معمولاً خودشان دوستان یکدیگرند) و (۲) «میانگین فاصله‌ی کوتاه» (به‌سبب تعداد کمی «پل» میان خوشه‌ها). این مدل پدیده‌های واقعی گوناگونی — از گسترش اپیدمی تا شایعه — را تبیین کرد و به یکی از پرجاذبه‌ترین مدل‌های علوم اجتماعی محاسباتی تبدیل شد.

۳. بازسازی‌های دیجیتال و «کوچک‌شدن» جهان
در عصر دیجیتال، خاصیت جهان کوچک با داده‌ی «واقعی» آزمون شده است: در فیس‌بوک، میانگین فا', 'e710748caa2a15c4fa35357b80230aa1c5854e488b1537c3082c6a88675aae05', 4, NOW(), NOW()),
('sec-card-423-5', 'doc-card-423', 'examples', 'مثال‌ها', 'بازی معروف «شش درجه‌ی جدایی» و «مسئله‌ی جهان کوچک» در نمایش و فیلم «شش درجه‌ی جدایی» (۱۹۹۰–۱۹۹۳) پدیده‌ای فرهنگی شد. در عصر معاصر، منطق همین زنجیره‌های کوتاه در طراحی سیستم‌های «پیشنهاد» شبکه‌های اجتماعی اجرا می‌شود: وقتی فیس‌بوک نشان می‌دهد «با X هشت دوست مشترک دارید»، در واقع دارد ساختار جهان کوچک را عملیاتی می‌کند.', 'a289a3c8f2f90d26b6c479ddcfb07ea96555ca79d612ad5e91cfbc6afbbc0ed3', 5, NOW(), NOW()),
('sec-card-423-6', 'doc-card-423', 'criticism', 'نقدها', '۱. اعتبار نمونه‌ی میلگرام: در مطالعه‌ی اصلی نرخ رسیدن نامه‌ها به مقصد پایین بود و «شش» به‌عنوان میانگین، تأیید آماری قوی ندارد.
۲. شبکه‌ی واقعی در برابر شبکه‌ی خیالی: آنچه میلگرام اندازه گرفت، زنجیره‌ی «پنداشته‌شده» توسط فرستنده بود، نه ساختار واقعی شبکه.
۳. بازسازی‌های دیجیتال: آزمایش «شش درجه» در ای‌بی (۲۰۱۱) م', '6cdf3be7f30c76854bd49f6b910910cb7b4aca6945264bcfdaa814a414322c48', 6, NOW(), NOW()),
('sec-card-423-7', 'doc-card-423', 'limitations', 'محدودیت‌ها', 'یانگینی حدود ۷ پیوند در دنیای فیزیکی نشان داد و در شبکه‌های اجتماعی مانند فیس‌بوک میانگین بسیار کوتاه‌تر (حدود ۳/۵ تا ۴ پیوند) است — «شش»ِ دهه‌ی ۱۹۶۰ در پلتفرم‌ها برقرار نیست.
۴. مرزهای فرهنگی: خاصیت «جهان کوچک» درون یک فرهنگ قوی است، اما بین گروه‌های اجتماعی بسیار دور (مثلاً بین کشورها) زنجیره‌ها بلندتر می‌شوند.', 'd3ea8e1620d9992b7c8eddf30f10363945e0184692dc6b2feabc251b4bd3e9b6', 7, NOW(), NOW()),
('sec-card-423-10', 'doc-card-423', 'references', 'منابع', 'مقاله «مسئله‌ی جهان کوچک» (استنلی میلگرام، ۱۹۶۷)؛ مقاله «دینامیک جمع‌شبکه‌های جهان کوچک» (وتس و استروگاتس، ۱۹۹۸).', '0532296aa4de42df996bfa8c07bb7630d7dd0209e03c508cc3285a201d9ee7ef', 10, NOW(), NOW());
