INSERT INTO `ai_references` (`id`, `reference_type`, `title`, `title_en`, `authors`, `publisher`, `journal`, `publication_year`, `isbn`, `doi`, `issn`, `source_url`, `citation_apa`, `image_urls`, `verification_status`, `created_at`, `updated_at`) VALUES
