INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-6', 'journal', 'عمل روزنامه‌نگاری', 'Journalism Practice', 'new-journal-6', NULL, 'international', NULL, NULL, 'عمل روزنامه‌نگاری، اخلاق روزنامه‌نگاری، رسانه‌های اجتماعی و خبر، پژوهش عملی روزنامه‌نگاری', NULL, '["https://www.tandfonline.com/doi/pdf/10.1080/17512786.2014.932755", "https://www.tandfonline.com/action/showPublicationsMenu?doi=10.1080/17512786"]', 'Journalism Practice مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی عمل روزنامه‌نگاری، اخلاق روزنامه‌نگاری، رسانه‌های اجتماعی و خبر و پژوهش عملی روزنامه‌نگاری است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «عمل روزنامه‌نگاری» و «اخلاق روزنامه‌نگاری» به‌شمار می‌رود. با ISSN 1751-2786 (چاپی) و 1751-2794 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.tandfonline.com/journals/rjpr20', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-7', 'journal', 'مجلهٔ بین‌المللی ارتباطات', 'International Journal of Communication', 'new-journal-7', NULL, 'international', NULL, NULL, 'پژوهش ارتباطات بین‌المللی، روش‌شناسی ارتباطات، ارتباطات و فناوری', NULL, '["https://ijoc.org/public/journals/1/favicon_en.png", "https://ijoc.org/public/journals/1/pageHeaderLogoImage_en.png", "https://ijoc.org/public/journals/1/homepageImage_en.jpg"]', 'International Journal of Communication (IJOC) مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی پژوهش ارتباطات بین‌المللی، روش‌شناسی ارتباطات، ارتباطات و فناوری است که توسط USC Annenberg Press به‌صورت رایگان (Open Access) منتشر می‌شود. این مجله مرجع اصلی «روش‌شناسی ارتباطات» و «ارتباطات محاسباتی» به‌شمار می‌رود. با ISSN 1932-8036 (فقط الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://ijoc.org', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-8', 'journal', 'پیام (پژوهش‌های علوم انسانی)', 'Peyam: Humanities Studies', 'new-journal-8', 'ایران', 'iranian', NULL, 'ایران', 'علوم انسانی، ارتباطات، جامعه‌شناسی، فرهنگ', NULL, '[]', 'Peyam (پیام) — پژوهش‌های علوم انسانی مجلهٔ معتبر و شناخته‌شده‌ی ایرانی در حوزه‌ی علوم انسانی، ارتباطات، جامعه‌شناسی و فرهنگ است که توسط پژوهشگاه علوم انسانی و مطالعات فرهنگی منتشر می‌شود. این مجله مرجع اصلی «ارتباطات در بافت ایران» به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در DOAJ/CrossRef/Wikidata، ISSN و وضعیت نمایه‌ی بین‌المللی (Scopus/ESCI) هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-9', 'journal', 'فرهنگ رسانه', 'Farhang-e Rasaneh (Media Culture)', 'new-journal-9', 'ایران', 'iranian', NULL, 'ایران', 'فرهنگ رسانه، مطالعات فرهنگی، ارتباطات', NULL, '[]', 'Farhang-e Rasaneh (فرهنگ رسانه) مجلهٔ معتبر و شناخته‌شده‌ی ایرانی در حوزه‌ی فرهنگ رسانه، مطالعات فرهنگی و ارتباطات است که توسط پژوهشگاه فرهنگ، هنر و ارتباطات منتشر می‌شود. این مجله مرجع اصلی «فرهنگ رسانه» در بافت ایرانی به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در پایگاه‌های بین‌المللی، ISSN و وضعیت نمایه‌ی بین‌المللی هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-10', 'journal', 'رسانه و فرهنگ', 'Rasaneh-ye Farhang (Media and Culture)', 'new-journal-10', 'ایران', 'iranian', NULL, 'ایران', 'رسانه و فرهنگ، ارتباطات، مطالعات فرهنگی', NULL, '[]', 'Rasaneh-ye Farhang (رسانه و فرهنگ) مجلهٔ شناخته‌شده‌ی ایرانی در حوزه‌ی رسانه و فرهنگ، ارتباطات و مطالعات فرهنگی است که ناشر آن احتمالاً دانشگاه تهران است (نیازمند تأیید). این مجله مرجع اصلی «رسانه و فرهنگ» در بافت ایرانی به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در پایگاه‌های بین‌المللی، ناشر، ISSN و وضعیت نمایه‌ی بین‌المللی هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-11', 'journal', 'مطالعات فرهنگ و ارتباطات', NULL, 'new-journal-11', 'ایران', 'iranian', NULL, 'ایران', 'فرهنگ، ارتباطات، مطالعات فرهنگی، رسانه', NULL, '[]', 'مطالعات فرهنگ و ارتباطات مجلهٔ فارسی در حوزه‌ی فرهنگ، ارتباطات، مطالعات فرهنگی و رسانه است که ناشر آن احتمالاً پژوهشگاه فرهنگ، هنر و ارتباطات است (نیازمند تأیید). این مجله مرجع اصلی «مطالعات فرهنگی» در بافت ایرانی به‌شمار می‌رود. هشدار: ممکن است با مجلهٔ انگلیسی «Journal of Culture-Communication Studies (JCCS)» (ردیف ۲۴ فهرست ۲۵ مجلهٔ موجود) تکراری باشد و در صورت تأیید تداخل باید حذف شود. پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-12', 'journal', 'فرهنگ رسانه (نشریهٔ انجمن فرهنگی رسانه ایران)', NULL, 'new-journal-12', 'ایران', 'iranian', NULL, 'ایران', 'فرهنگ رسانه، ارتباطات', NULL, '[]', 'فرهنگ رسانه (نشریهٔ انجمن فرهنگی رسانه ایران) مجلهٔ فارسی در حوزه‌ی فرهنگ رسانه و ارتباطات است که توسط انجمن فرهنگی رسانه ایران منتشر می‌شود. این کم‌اعتبارترین مورد فهرست ۱۵ مجلهٔ جدید است؛ اطلاعات آن ناقص است و ممکن است با مجلهٔ «Farhang-e Rasaneh (فرهنگ رسانه)» (ردیف ۲.۹) تداخل داشته باشد. پیش از استفاده باید از داخل ایران تأیید شود و در صورت عدم‌تأیید، این مورد باید حذف شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-13', 'journal', 'اخلاق رسانه', 'Journal of Media Ethics', 'new-journal-13', NULL, 'international', NULL, NULL, 'اخلاق رسانه، اخلاق روزنامه‌نگاری، حریم خصوصی، حقوق رسانه', NULL, '["https://www.tandfonline.com/doi/pdf/10.1080/23736992.2016.1242955", "https://www.tandfonline.com/action/showPublicationsMenu?doi=10.1080/23736992"]', 'Journal of Media Ethics مجلهٔ بین‌المللی و Q3 (SCImago و Web of Science — Communication / Ethics) در حوزه‌ی اخلاق رسانه، اخلاق روزنامه‌نگاری، حریم خصوصی و حقوق رسانه است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «اخلاق رسانه» و پوشش‌دهنده‌ی خلأ مجلات اخلاق رسانه است. با ISSN 2373-6992 (چاپی) و 2373-700X (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.tandfonline.com/journals/hjmc20', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-14', 'journal', 'مطالعات بین‌المللی خاورمیانه', 'International Journal of Middle East Studies', 'new-journal-14', NULL, 'international', NULL, NULL, 'مطالعات خاورمیانه، تاریخ خاورمیانه، فرهنگ خاورمیانه، رسانه خاورمیانه', NULL, '["https://www.cambridge.org/core/services/aop-cambridge-core/cover/10.1017/S00207438", "https://www.cambridge.org/core/brand-assets"]', 'International Journal of Middle East Studies (IJMES) مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science — Middle Eastern / Islamic Studies) در حوزه‌ی مطالعات خاورمیانه، تاریخ خاورمیانه، فرهنگ خاورمیانه و رسانه خاورمیانه است که توسط Cambridge University Press منتشر می‌شود. این مجله مرجع اصلی «مطالعات خاورمیانه» از منظر پژوهش غربی است. با ISSN 0020-7438 (چاپی) و 1471-6380 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.cambridge.org/core/journals/international-journal-of-middle-east-studies', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-15', 'journal', 'مجلهٔ خاورمیانه', 'Middle East Journal', 'new-journal-15', NULL, 'international', NULL, NULL, 'مطالعات خاورمیانه، سیاست خاورمیانه، فرهنگ خاورمیانه، رسانه خاورمیانه', NULL, '["https://www.middleeastjournal.org/cover", "https://www.mei.edu/images/logos/middle-east-journal-logo.png"]', 'Middle East Journal مجلهٔ بین‌المللی و Q2 (SCImago و Web of Science — Middle Eastern Studies) در حوزه‌ی مطالعات خاورمیانه، سیاست خاورمیانه، فرهنگ خاورمیانه و رسانه خاورمیانه است که توسط Columbia University منتشر می‌شود. این مجله (بنیان‌گذاری ۱۹۴۷) مرجع اصلی «مطالعات خاورمیانه» از منظر تاریخی/سیاسی است. با ISSN 0026-3292 (چاپی) و 1548-9251 (الکترونیکی — نیازمند تأیید)، در Scopus، Web of Science و Scimago نمایه شده است؛ این مجله در CrossRef ثبت ندارد اما مجلهٔ معتبر دانشگاه کلمبیا است.', 'https://www.middleeastjournal.org', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');

